#!/usr/bin/env node
// Register feature-level lifecycle subscriptions for every app version in
// scripts/lifecycle-apps.config.json (generated by
// resolve-lifecycle-features.mjs), pointing them all at the
// telemetry-dashboard webhook: <webhookBaseUrl>/api/webhooks/lifecycle.
//
// The config is a full matrix — apps × {draft, live} × lifecycle features —
// and every feature id is registered separately (feature ids differ per
// version, so each promote / new draft requires re-resolving + re-running).
//
// Usage:
//   node scripts/register-lifecycle-subscriptions.mjs [--dry-run] [--app <name>]
//       [--version-status <draft|live>] [--webhook-base-url <url>]
//
// For each feature it runs update_app_lifecycle_subscription with ALL
// lifecycle events for the feature's kind (is_sync: false — async mode),
// then verifies via get_app_lifecycle_subscriptions(app_id) that every
// planned event is subscribed at the expected URL.
//
// Token resolution: MONDAY_API_TOKEN env var, else ~/.config/mapps/.mappsrc
// (JSON field `accessToken`). The token value is never printed.

import { readFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { parseArgs } from 'node:util';
import { EVENTS_BY_KIND } from './lifecycle-kinds.mjs';

const API_URL = process.env.MONDAY_API_URL || 'https://api.monday.com/v2';
const API_VERSION = '2026-04';
const CONFIG_URL = new URL('./lifecycle-apps.config.json', import.meta.url);

const HELP = `register-lifecycle-subscriptions.mjs — register feature lifecycle webhooks

Usage:
  node scripts/register-lifecycle-subscriptions.mjs [options]

Options:
  --dry-run                  Print the planned mutations without calling the API
  --app <name>               Only process the app whose name or appId matches
  --version-status <status>  Only process versions with this status (draft|live)
  --webhook-base-url <url>   Override the config's webhookBaseUrl (e.g. the
                             one-command re-point to live1 after release)
  --help                     Show this help

Reads scripts/lifecycle-apps.config.json (GENERATED — run
resolve-lifecycle-features.mjs first):
  { "webhookBaseUrl", "apps": [{ "name", "appId", "versions": [{ "versionId",
    "versionStatus", "features": [{ "featureId", "kind" }] }] }] }

Token: MONDAY_API_TOKEN env var, else accessToken from ~/.config/mapps/.mappsrc.
`;

// Flatten the config into one registration job per feature per version,
// applying the --app / --version-status filters. Unknown kinds are warned
// about and skipped — never guessed.
export function planRegistrations(config, { app, versionStatus } = {}) {
  const jobs = [];
  const warnings = [];
  let apps = Array.isArray(config.apps) ? config.apps : [];
  if (app) apps = apps.filter((a) => a.name === app || String(a.appId) === String(app));
  for (const a of apps) {
    for (const version of Array.isArray(a.versions) ? a.versions : []) {
      if (versionStatus && version.versionStatus !== versionStatus) continue;
      for (const feature of Array.isArray(version.features) ? version.features : []) {
        const events = EVENTS_BY_KIND[feature.kind];
        if (!events) {
          warnings.push(
            `[${a.name}] feature ${feature.featureId} has unknown kind "${feature.kind}" — skipping (expected one of: ${Object.keys(EVENTS_BY_KIND).join(', ')})`
          );
          continue;
        }
        jobs.push({
          appId: String(a.appId),
          appName: a.name,
          versionId: String(version.versionId),
          versionStatus: version.versionStatus,
          featureId: feature.featureId,
          entityId: String(feature.featureId),
          kind: feature.kind,
          events,
        });
      }
    }
  }
  return { jobs, warnings };
}

// Compare get_app_lifecycle_subscriptions rows against the jobs planned for
// that app: every planned event must be subscribed at the expected URL.
// Subscriptions for entities outside the plan (e.g. a version we filtered
// out) are ignored. Returns a list of human-readable problems (empty = ok).
export function verifySubscriptions(subscriptions, jobs, webhookUrl) {
  const problems = [];
  const rows = Array.isArray(subscriptions) ? subscriptions : [];
  for (const job of jobs) {
    const mine = rows.filter((s) => String(s.entity_id) === job.entityId);
    for (const action of job.events) {
      const eventType = `${job.kind}:${action}`;
      const sub = mine.find((s) => s.event_type === eventType);
      if (!sub) {
        problems.push(
          `[${job.appName}/${job.versionStatus}] feature ${job.featureId}: missing subscription for ${eventType} (expected ${action} at ${webhookUrl})`
        );
      } else if (sub.webhook_url !== webhookUrl) {
        problems.push(
          `[${job.appName}/${job.versionStatus}] feature ${job.featureId}: ${eventType} points at ${sub.webhook_url}, expected ${webhookUrl}`
        );
      }
    }
  }
  return problems;
}

function resolveToken() {
  if (process.env.MONDAY_API_TOKEN) return process.env.MONDAY_API_TOKEN;
  const rcPath = join(homedir(), '.config', 'mapps', '.mappsrc');
  try {
    const parsed = JSON.parse(readFileSync(rcPath, 'utf8'));
    if (typeof parsed.accessToken === 'string' && parsed.accessToken.length > 0) {
      return parsed.accessToken;
    }
    console.error(`note: ${rcPath} has no accessToken field`);
  } catch (err) {
    console.error(`note: could not read ${rcPath} (${err.message})`);
  }
  return null;
}

async function graphql(token, query) {
  const res = await fetch(API_URL, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: token,
      'API-Version': API_VERSION,
    },
    body: JSON.stringify({ query }),
  });
  const text = await res.text();
  let json;
  try {
    json = JSON.parse(text);
  } catch (err) {
    throw new Error(`monday API returned non-JSON (HTTP ${res.status}): ${text.slice(0, 300)} (${err.message})`);
  }
  if (!res.ok) {
    throw new Error(`monday API HTTP ${res.status}: ${JSON.stringify(json.errors ?? json).slice(0, 500)}`);
  }
  if (Array.isArray(json.errors) && json.errors.length > 0) {
    throw new Error(`monday API errors: ${JSON.stringify(json.errors).slice(0, 800)}`);
  }
  if (!json.data) throw new Error('monday API response has no data');
  return json.data;
}

function buildRegisterMutation(job, webhookUrl) {
  const eventLines = job.events
    .map(
      (action) =>
        `        { event_type: ${JSON.stringify(`${job.kind}:${action}`)}, webhook_url: ${JSON.stringify(webhookUrl)}, is_sync: false }`
    )
    .join('\n');
  return `mutation {
  update_app_lifecycle_subscription(
    entity_identifier: ${JSON.stringify(job.entityId)}
    entity_type: "appFeature"
    input: {
      lifecycle_events: [
${eventLines}
      ]
    }
  ) { id event_type webhook_url is_sync }
}`;
}

// version_id is undocumented but real (schema-introspected 2026-07-24) and
// REQUIRED for correctness: without it the query does NOT return the union
// of all versions' subscriptions (a draft registered seconds earlier came
// back empty), so verification must ask per version explicitly.
function buildVerifyQuery(appId, versionId) {
  return `query {
  get_app_lifecycle_subscriptions(app_id: ${JSON.stringify(String(appId))}, version_id: ${JSON.stringify(String(versionId))}) {
    id entity_id event_type webhook_url is_sync
  }
}`;
}

// monday forbids touching live versions' subscriptions (403 FORBIDDEN_EXCEPTION,
// discovered 2026-07-24 — earlier live registrations were also wiped server-side).
// Drafts are the only registrable state, so this failure mode is expected and
// reported as a skip, not a failure.
export function isLiveImmutableError(message) {
  return /cannot be modified for live app versions/i.test(String(message ?? ''));
}

function loadConfig() {
  let raw;
  try {
    raw = readFileSync(CONFIG_URL, 'utf8');
  } catch (err) {
    console.error(`cannot read lifecycle-apps.config.json next to this script: ${err.message}`);
    process.exit(1);
  }
  let config;
  try {
    config = JSON.parse(raw);
  } catch (err) {
    console.error(`lifecycle-apps.config.json is not valid JSON: ${err.message}`);
    process.exit(1);
  }
  if (!Array.isArray(config.apps)) {
    console.error('lifecycle-apps.config.json must have an "apps" array — run resolve-lifecycle-features.mjs first');
    process.exit(1);
  }
  return config;
}

async function main() {
  const { values } = parseArgs({
    options: {
      'dry-run': { type: 'boolean', default: false },
      app: { type: 'string' },
      'version-status': { type: 'string' },
      'webhook-base-url': { type: 'string' },
      help: { type: 'boolean', default: false },
    },
  });

  if (values.help) {
    console.log(HELP);
    return;
  }
  if (values['version-status'] && !['draft', 'live'].includes(values['version-status'])) {
    console.error(`--version-status must be draft or live — got: ${values['version-status']}`);
    process.exit(1);
  }

  const dryRun = values['dry-run'];
  const config = loadConfig();

  const base = String(values['webhook-base-url'] ?? config.webhookBaseUrl ?? '').replace(/\/+$/, '');
  if (!base) {
    console.error('webhookBaseUrl is empty — set it in lifecycle-apps.config.json or pass --webhook-base-url');
    process.exit(1);
  }
  if (!/^https:\/\//.test(base)) {
    console.error(`webhookBaseUrl must start with https:// — got: ${base}`);
    process.exit(1);
  }
  const webhookUrl = `${base}/api/webhooks/lifecycle`;

  const { jobs, warnings } = planRegistrations(config, {
    app: values.app,
    versionStatus: values['version-status'],
  });
  for (const w of warnings) console.warn(w);
  if (values.app && jobs.length === 0 && warnings.length === 0) {
    console.error(`--app ${values.app} matched no registrable features; apps in config: ${config.apps.map((a) => a.name || a.appId).join(', ')}`);
    process.exit(1);
  }

  let token = null;
  if (!dryRun) {
    token = resolveToken();
    if (!token) {
      console.error('missing token: set MONDAY_API_TOKEN or run `mapps init -t <token>` first');
      process.exit(1);
    }
  }

  console.log(`webhook URL: ${webhookUrl}${dryRun ? '  (dry run — no API calls)' : ''}`);
  console.log(`${jobs.length} feature registration(s) planned across ${new Set(jobs.map((j) => j.appId)).size} app(s)`);

  const failures = [...warnings];
  const liveSkips = [];
  // Group per (app, version): registration is per feature, but verification
  // must query per version (see buildVerifyQuery).
  const jobsByVersion = new Map();
  for (const job of jobs) {
    const key = `${job.appId}::${job.versionId}`;
    if (!jobsByVersion.has(key)) jobsByVersion.set(key, []);
    jobsByVersion.get(key).push(job);
  }

  for (const versionJobs of jobsByVersion.values()) {
    const { appId, versionId, versionStatus } = versionJobs[0];
    const label = `${versionJobs[0].appName || appId}/${versionStatus}`;
    const registered = [];

    for (const job of versionJobs) {
      const mutation = buildRegisterMutation(job, webhookUrl);
      if (dryRun) {
        console.log(`\n[${label}] planned mutation for ${job.entityId} (${job.kind}):\n${mutation}`);
        continue;
      }
      console.log(`\n[${label}] registering ${job.events.length} ${job.kind} events for feature ${job.entityId}…`);
      try {
        const data = await graphql(token, mutation);
        console.log(`  ok — ${data.update_app_lifecycle_subscription.length} subscriptions returned`);
        registered.push(job);
      } catch (err) {
        if (isLiveImmutableError(err.message)) {
          console.warn(`  live version is immutable — skipped (monday forbids modifying live subscriptions; the draft carries them instead)`);
          liveSkips.push(`${label}/${job.entityId}`);
        } else {
          console.error(`[${label}] registration failed for ${job.entityId}: ${err.message}`);
          failures.push(`${label}/${job.entityId}`);
        }
      }
    }

    if (!dryRun && registered.length > 0) {
      try {
        const data = await graphql(token, buildVerifyQuery(appId, versionId));
        const problems = verifySubscriptions(data.get_app_lifecycle_subscriptions, registered, webhookUrl);
        if (problems.length > 0) {
          for (const p of problems) console.error(`  VERIFY FAIL ${p}`);
          failures.push(...problems);
        } else {
          console.log(`[${label}] verified: all ${registered.length} feature(s) fully subscribed at ${webhookUrl}`);
        }
      } catch (err) {
        console.error(`[${label}] verification query failed: ${err.message}`);
        failures.push(`${label}/verify`);
      }
    }
  }

  if (liveSkips.length > 0) {
    console.warn(`\n${liveSkips.length} live-version feature(s) skipped (immutable): ${liveSkips.join(', ')}`);
  }
  if (failures.length > 0) {
    console.error(`\ndone with ${failures.length} failure(s)`);
    process.exit(1);
  }
  console.log('\ndone.');
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((err) => {
    console.error(`register-lifecycle-subscriptions failed: ${err.message}`);
    process.exit(1);
  });
}
